/* Deterministic application bootstrap. The host loads modules; bootstrap validates and starts them. */
window.GameBootstrap=(()=>{let status='idle';return Object.freeze({get status(){return status},async start(){if(status!=='idle')throw new Error('Bootstrap already '+status);status='starting';try{const required=['GameEvents','GameState','GameStorage','GameConfig','GameSystems','GameDiagnostics','GameSchemaValidator'];for(const name of required)if(!window[name])throw new Error('Missing core dependency: '+name);window.GameEvents.emit('app:booting');await window.GameSystems.startAll({events:GameEvents,state:GameState,storage:GameStorage,config:GameConfig,diagnostics:GameDiagnostics});status='ready';window.GameEvents.emit('app:ready');GameDiagnostics.info('APP_READY',{systems:GameSystems.status()});return true}catch(error){status='failed';console.error('[Bootstrap] failed',error);window.GameEvents?.emit('app:failed',{error});throw error}},async stop(){if(status!=='ready')return;status='stopping';await window.GameSystems.stopAll();status='stopped';window.GameEvents.emit('app:stopped')}})})();
